import os, select, time, math

class Port:
    def __init__(self, n):
        self.n=n
        self.fd=os.open(f'/dev/robot/d{n}', os.O_RDONLY|os.O_NONBLOCK)
        self.buf=b''
        self.last=None
        self.queue=[]
    def poll(self):
        while True:
            r,_,_=select.select([self.fd],[],[],0)
            if not r: break
            try: d=os.read(self.fd,65536)
            except BlockingIOError: break
            if not d: break
            self.buf+=d
        while b'\n' in self.buf:
            line,self.buf=self.buf.split(b'\n',1)
            s=line.decode().strip()
            if s:
                self.last=s
                self.queue.append(s)
    def latest(self, wait=1.5):
        # drain, then wait for a fresh line
        self.poll(); self.last=None
        t0=time.time()
        while time.time()-t0<wait:
            self.poll()
            if self.last is not None: return self.last
            time.sleep(0.02)
        return self.last

class Bot:
    def __init__(self):
        self.p={n:Port(n) for n in [0,1,2,3,6,7,9]}
        self.wfd={}
    def wr(self,n,s):
        fd=os.open(f'/dev/robot/d{n}', os.O_WRONLY)
        os.write(fd,(s+'\n').encode()); os.close(fd)
    def heading(self):
        s=self.p[2].latest(); return float(s) if s else None
    def scan(self):
        s=self.p[1].latest(); return [float(x) for x in s.split(',')] if s else None
    def move(self,d):
        self.p[6].poll(); self.p[6].queue.clear()
        self.wr(4,str(d))
        t0=time.time()
        while time.time()-t0<10:
            self.p[6].poll()
            if self.p[6].queue: return float(self.p[6].queue.pop(0))
            time.sleep(0.02)
        return None
    def turn(self,a):
        self.wr(5,str(a)); time.sleep(0.3)
    def status(self):
        return self.p[9].latest()
    def radio_send(self,s): self.wr(8,s)
    def radio_recv(self):
        self.p[3].poll(); q=self.p[3].queue[:]; self.p[3].queue.clear(); return q
import time, math, json, os
from ctl import Ctl, angdiff

K_W=0.89
CELL=0.57
DIRS={0:(1,0),90:(0,1),180:(-1,0),270:(0,-1)}

def cmd_for(v):  # v m/s -> wheel cmd
    c=v/0.0066
    return c

class Nav(Ctl):
    def wheels(self,l,r):
        self.wr(4,f'{l:.1f}'); self.wr(5,f'{r:.1f}')
    def drive(self,v,w):  # v m/s fwd, w deg/s
        base=cmd_for(v)
        dl=-w/(2*K_W); dr=w/(2*K_W)
        self.wheels(base+dl, base+dr)
    def stop(self): self.wheels(0,0)
    def stalled(self):
        self.p[7].poll(); return self.p[7].last=='1'
    def sc(self):
        s=self.scan()
        while s is None:
            time.sleep(0.05); s=self.scan()
        return [x if x>0 else 0.05 for x in s]
    def spin_to(self,target,tol=5):
        t0=time.time()
        while time.time()-t0<14:
            h=self.heading()
            if h is None: continue
            e=angdiff(target,h)
            if abs(e)<tol:
                self.stop(); return True
            w=max(min(e*1.8,80),-80)
            if abs(w)<25: w=25*(1 if w>0 else -1)
            self.wheels(-w/1.78, w/1.78)
            time.sleep(0.1)
        self.stop(); return False

class Explorer:
    def __init__(self):
        self.b=Nav()
        self.cx=0; self.cy=0; self.facing=0
        self.visited=set(); self.stack=[]
        self.walls={}
        self.log=open('/memory/grid.log','a',buffering=1)
        self.t0=time.time()
        self.rxlog=[]
    def lg(self,m): self.log.write(f'{time.time()-self.t0:7.1f} {m}\n')
    def checks(self):
        b=self.b
        b.p[9].poll(); b.p[0].poll()
        st=b.p[9].last; s0=b.p[0].last
        if st and 'goal=0' not in st: self.lg(f'GOALFLAG {st}')
        if s0 and s0!='0': self.lg(f'D0 {s0}')
        for m in b.radio_recv():
            self.lg(f'RX: {m}')
        b.radio_send(f'A cell=({self.cx},{self.cy})')
    def openness(self,s):
        return {0:s[0],90:s[4],180:s[8],270:s[12]}
    def go(self,d):
        """move one cell toward absolute dir d. return True if advanced."""
        b=self.b
        b.spin_to(d)
        self.facing=d
        s=b.sc(); s0=s[0]
        use_wall=s0<2.7
        target=s0-CELL
        t0=time.time(); last=t0; est=0.0
        stall_t=None; power=False
        arrived=False
        while True:
            s=b.sc()
            now=time.time(); dt=now-last; last=now
            est+=(0.4 if power else 0.28)*dt
            h=b.heading(); e=angdiff(d,h) if h is not None else 0
            w=max(min(1.6*e,30),-30)
            if s[4]<0.45 and s[12]<0.45:
                w+=max(min((s[4]-s[12])*60,20),-20)

